'use strict';
let D,L,state={notes:{},ratings:{},learned:{}},clockHandle;
const main=document.querySelector('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bullets=a=>'<ul>'+a.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>';
const link=(href,label)=>`<a href="${esc(href)}">${esc(label)}</a>`;
const refs=a=>'<div class="refs">'+(a||[]).map(id=>{const l=L.find(l=>l.id===id);return l?link('#law/'+id,l.family+' · '+l.article):esc(id)}).join(' · ')+'</div>';
const heading=(k,t,s='')=>`<p class="eyebrow">${esc(k)}</p><h1>${esc(t)}</h1>${s?`<p class="lede">${esc(s)}</p>`:''}`;
const source=s=>`<p class="source">${esc(s)}</p>`;
function save(){try{localStorage.setItem('ai-ethics-atlas-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. Export your notes before leaving.')}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function note(id){return `<label class="notes-label" for="note-${esc(id)}">My answer / notes</label><textarea class="notes" id="note-${esc(id)}" data-note="${esc(id)}" placeholder="Write your reasoning before revealing the answer…">${esc(state.notes[id]||'')}</textarea>`}
function rating(id){return `<div class="confidence"><span>My confidence</span>${['Revisit','Developing','Ready'].map(v=>`<button data-rate="${id}" data-value="${v}" class="${state.ratings[id]===v?'selected':''}">${v}</button>`).join('')}</div>`}
function reveal(html){return `<details><summary>Reveal answer outline</summary><div class="detail-content">${html}</div></details>`}
function cards(a,render){return '<div class="grid">'+a.map(render).join('')+'</div>'}
function timer(minutes){return `<div class="toolbar"><span class="timer" id="timer">${minutes}:00</span><button data-timer="${minutes}">Start timer</button><span class="muted">Practice timing, not an official limit.</span></div>`}
function question(q,weight){return `<article class="card"><p class="meta">${q.id} · ${q.format?(q.format==='long'?'<span class="tag gold">Long · 1 A4 page</span>':'<span class="tag">Short · ¼ page</span>')+' · ':''}${esc(q.kind)} · ${weight||q.points} practice points</p><h2>${esc(q.prompt)}</h2>${note(q.id)}${reveal(bullets(q.answer)+`<p><strong>Common weakness:</strong> ${esc(q.trap)}</p>`+source(q.source))}${rating(q.id)}</article>`}
function render(){clearInterval(clockHandle);let [route,id]=parseRoute();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.section===(EXTRA_NAV[route]?EXTRA_NAV[route]:route==='law'?'legal':route==='mock'?'mocks':route==='defense'?'oral':route)));document.querySelector('#breadcrumb').textContent=breadcrumb(route,id);document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-button').setAttribute('aria-expanded','false');
if(route==='home')main.innerHTML=heading('5DA06 / Study workspace','AI Ethics: study and prepare.','Choose exam revision or your group project. Use the reference library whenever you need the original source.')+examBanner()+`<div class="grid pathway-grid"><section class="card pathway"><span class="tag">Exam revision</span><h2>Understand. Apply. Practise.</h2><p>Review the lecture concepts, write your own answer, then compare it with the outline.</p><ol><li>${link('#course','Study the 13 course modules')}</li><li>${link('#practice','Work through 40 practice questions')}</li><li>${link('#mocks','Try a timed mock exam')}</li></ol></section><section class="card pathway"><span class="tag">Seven-minute group project</span><h2>Prepare the bank’s recommendation.</h2><p>Use the original scenario and prepare a justified position for your role.</p><ol><li>${link('#scenario','Read the unchanged project brief')}</li><li>${link('#roles','Choose your role and reading material')}</li><li>${link('#project','Discuss the proposed recommendations')}</li><li>${link('#rehearsal','Rehearse the seven-minute dialogue')}</li><li>${link('#oral','Practise the jury questions')}</li></ol></section></div><section class="card"><h2>Your study progress</h2><div class="stats"><div class="stat"><strong>${Object.values(state.learned).filter(Boolean).length} / 13</strong><span>Modules reviewed</span></div><div class="stat"><strong>${Object.values(state.ratings).filter(v=>v==='Ready').length}</strong><span>Answers marked ready</span></div><div class="stat"><strong>${Object.values(state.notes).filter(Boolean).length}</strong><span>Saved notes</span></div></div><p class="muted">Your notes stay in this browser. Export them to keep a backup or move devices.</p></section><div class="grid"><section class="card"><h2>Reference library</h2><p>Look up an article or return to the slides behind a concept.</p><p>${link('#legal','Read the laws →')} · ${link('#sources','Open course sources →')}</p></section><section class="card"><h2>Study offline</h2><p>Download the scenario, role reading guide, exam pack and legal appendix in PDF or Word.</p>${link('#downloads','View downloads →')}</section></div>`;
else if(route==='course'&&!id)main.innerHTML=heading('01 / Understand','The course map','Learn the concepts, then use them to explain a concrete case.')+cards(D.modules,m=>`<a class="card title-link" href="#course/${m.id}"><p class="meta">${state.learned[m.id]?'Reviewed ✓':'Module'}</p><h2>${esc(m.title)}</h2><p>${esc(m.question)}</p><span>${m.concepts.length} concepts · Open →</span></a>`);
else if(route==='course'){const m=D.modules.find(m=>m.id===id);if(!m)return missing();main.innerHTML=link('#course','← Course map')+heading('Course module',m.title,m.question)+`<div class="reading">${m.concepts.map(c=>`<section class="card"><h2>${esc(c.term)}</h2>${bullets(c.points)}</section>`).join('')}<section class="card"><h2>Apply it to the bank</h2>${bullets(m.case)}<h3>Common weaknesses</h3>${bullets(m.pitfalls)}<h3>Try this</h3><p>${esc(m.task)}</p>${note(m.id)}<button data-learn="${m.id}">${state.learned[m.id]?'Mark as not reviewed':'Mark reviewed'}</button></section>${source(m.source+' · '+m.transcript)}<h2>Related practice</h2>${bulletsLinks(D.questions.filter(q=>q.module===id).map(q=>['#practice/'+q.id,q.id+' · '+q.prompt]))}</div>`}
else if(route==='practice'&&!id){main.innerHTML=heading('02 / Write','Written practice','Answer first. Reveal the outline. Check the mechanism, case application and trade-off.')+`<div class="toolbar"><select id="module-filter" aria-label="Filter by module"><option value="">All modules</option>${D.modules.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select><input id="question-filter" type="search" placeholder="Filter questions" aria-label="Filter questions"></div><div id="question-list"></div>`;filterQuestions()}
else if(route==='practice'){const q=D.questions.find(q=>q.id===id);if(!q)return missing();main.innerHTML=link('#practice','← All questions')+heading(q.id,'Develop your argument')+timer(q.minutes)+question(q)}
else if(route==='mocks')main.innerHTML=heading('03 / Rehearse','Four practice papers','Each paper totals 20 practice points. The 60-minute timing and rubric are study tools, not the instructors’ official exam format.')+cards(D.mocks,m=>`<a class="card title-link" href="#mock/${m.id}"><p class="meta">${m.id} · 60 minutes · 20 points</p><h2>${esc(m.title)}</h2><p>Four questions. Write a reasoned answer before opening the outline.</p><span>Begin →</span></a>`)+rubric();
else if(route==='mock'){const m=D.mocks.find(m=>m.id===id);if(!m)return missing();main.innerHTML=link('#mocks','← Practice papers')+heading(m.id,m.title)+timer(m.minutes)+m.questions.map((id,i)=>question(D.questions.find(q=>q.id===id),m.weights[i])).join('')+rubric()}
else if(route==='rehearsal')renderRehearsal(id);
else if(route==='scenario')main.innerHTML=heading('Group project / Step 1','Original scenario','The text below is reproduced unchanged from your project document.')+projectSteps('scenario')+scenarioPanel()+`<div class="toolbar">${link('#rehearsal','Open the seven-minute rehearsal dialogue →')}${link('#roles','Next: prepare your role →')}</div>`;
else if(route==='roles'&&!id)main.innerHTML=heading('Group project / Step 2','Prepare your role','Choose one of the five roles from the course instructions. Each guide connects the reading to the bank scenario and a concrete task for your discussion.')+projectSteps('roles')+`<div class="toolbar">${link('#scenario','Read the original scenario →')}${link('course/video_case_studies_guidelines.pdf#page=2','Read the role cards →')}</div>`+roleCards();
else if(route==='roles'){const role=D.roleReading.find(r=>r.id===id);if(!role){main.innerHTML=heading('Group project / Role preparation','Choose your role','Select a role below to open its reading material and preparation checklist.')+projectSteps('roles')+roleCards();return;}main.innerHTML=link('#roles','← All roles')+heading('Group project / Role preparation',role.name,role.mission)+projectSteps('roles')+`<div class="reading"><h2>1. Read and connect to the scenario</h2>${role.readings.map(r=>`<section class="card"><h2>${esc(r.title)}</h2><p>${esc(r.why)}</p>${refs(r.refs)}${bulletsLinks((r.modules||[]).map(id=>['#course/'+id,D.modules.find(m=>m.id===id).title]))}${bulletsLinks(r.links||[])}</section>`).join('')}<section class="card"><h2>2. Prepare for the discussion</h2>${bullets(role.prepare)}</section><section class="card"><h2>3. Rehearse your answer</h2><p>${esc(role.question)}</p>${note('role-'+role.id)}${reveal(bullets(role.answer))}</section>${role.id==='compliance'?link('#oral','Continue with the 30 Compliance Officer drills →'):''}</div>`}
else if(route==='project'){const p=D.project;main.innerHTML=heading('Group project / Step 3','Recommendations and discussion','Use these proposed positions to prepare the group’s recommendation and explain the trade-offs.')+projectSteps('project')+`<div class="reading"><section class="callout"><p>${esc(p.basis)}</p><p>${link("#scenario","Original scenario")} · ${link("#roles","Reading for each role")}</p></section><section class="card"><h2>Compliance Officer: additional speaking practice</h2>${p.opening.map(s=>`<p class="opening">${esc(s)}</p>`).join('')}${source(p.opening_note)}</section><h2>Proposed decisions</h2>${p.usecases.map(c=>`<section class="card"><span class="tag">${esc(c.decision)}</span><h2>${esc(c.name)}</h2><p>${esc(c.why)}</p>${bullets(c.controls)}${refs(c.refs)}</section>`).join('')}<h2>Release gates and owners</h2>${p.gates.map(g=>`<section class="card"><h3>${esc(g.step)}</h3><p class="meta">${esc(g.owner)}</p><p>${esc(g.evidence)}</p></section>`).join('')}<section class="card"><h2>Evidence to bring to the board</h2>${bullets(p.checklist)}</section><section class="card"><h2>Seven-minute video structure</h2>${table(['Time','Focus'],p.video)}</section><section class="card"><h2>Questions for the other roles</h2>${table(['Role','Question'],p.challenge_others)}</section>${note('project')}${link('course/AI%20Ethics%20-%20Group%20Project.docx','Download the original project brief')}</div>`}
else if(route==='oral'&&!id)main.innerHTML=heading('Group project / Step 5','Prepare the oral defense','Explain the reasoning behind your recommendation. Use the detailed questions to test understanding, not to memorise a speech.')+projectSteps('oral')+deadlineNotice()+`<div class="toolbar">${link('downloads/oral-defense-pack.pdf','Download oral pack · PDF')}${link('downloads/oral-defense-pack.docx','Word')}<button id="random-defense">Practise a random question</button></div><section class="card"><h2>What the instructors expect</h2><p>${esc(D.defense.basis)}</p>${bullets(D.defense.method)}</section><details><summary>The decision every member should know</summary><div class="detail-content">${table(['Application','Decision','Conditions'],D.defense.decisions)}</div></details><h2>Explanations and contestability</h2><p>The instructor explicitly highlighted these as possible follow-up questions.</p><div class="grid"><section class="card"><h3>What the customer receives</h3>${bullets(D.defense.explanations.format)}</section><section class="card"><h3>What the customer can challenge</h3>${bullets(D.defense.explanations.grounds)}</section></div><details open><summary>From a challenge to a meaningful review</summary><div class="detail-content">${bullets(D.defense.explanations.process)}<h3>Example to explain aloud</h3>${bullets(D.defense.explanations.example)}${refs(['Dun_Bradstreet','CCD2-18','GDPR-22'])}</div></details><details><summary>Drawbacks of explanation formats</summary><div class="detail-content">${bullets(D.defense.explanations.tradeoffs)}</div></details><h2>Prepare by role</h2>${cards(D.defense.roles,role=>`<section class="card"><h3>${esc(role.name)}</h3>${bullets(role.focus)}<h4>Six questions to practise</h4>${bulletsLinks(role.questions.map(id=>{const q=D.defense.questions.find(q=>q.id===id);return ['#defense/'+id,q.id+' · '+q.question]}))}<h4>Course reading</h4>${bulletsLinks(role.reading.map(id=>['#course/'+id,D.modules.find(m=>m.id===id).title]))}</section>`)}<section class="card"><h2>If you do not know</h2>${bullets(D.defense.unknown)}<p>Be specific about the limit. Then explain what it would change in the recommendation.</p></section><details><summary>Facts, policies and evidence still needed</summary><div class="detail-content">${table(['Status','What to say'],D.defense.status)}</div></details><section class="card"><h2>Final rehearsal checklist</h2>${bullets(D.defense.rehearsal)}</section><details><summary>Additional legal practice: 30 Compliance Officer drills</summary><div class="detail-content"><p>Supplementary legal questions from the study atlas.</p><button id="random-oral">Random legal question</button>${cards(D.oral,o=>`<a class="card title-link" href="#oral/${o.id}"><p class="meta">${o.id}</p><h3>${esc(o.question)}</h3></a>`)}</div></details>`;
else if(route==='defense'){const q=D.defense.questions.find(q=>q.id===id);if(!q){location.hash='oral';return}main.innerHTML=link('#oral','← Oral defense guide')+heading(q.id,q.question,`Lead: ${q.lead}. Support: ${q.support}.`)+`<p>Give a 20–30 second answer, then use the remaining practice minute for the follow-up.</p>`+timer(1)+`<section class="card reading">${note(q.id)}${reveal(bullets(q.answer)+refs(q.refs)+bulletsLinks(q.modules.map(id=>['#course/'+id,D.modules.find(m=>m.id===id).title])))}<h2>Follow-up</h2><p>${esc(q.followup)}</p><details><summary>Weak answer to avoid</summary><div class="detail-content"><p>${esc(q.avoid)}</p></div></details>${rating(q.id)}<div class="toolbar"><button id="random-defense">Another question</button>${link('#defense/'+D.defense.questions[(D.defense.questions.indexOf(q)+1)%D.defense.questions.length].id,'Next →')}</div></section>`}
else if(route==='oral'){const o=D.oral.find(o=>o.id===id);if(!o)return missing();const next=D.oral[(D.oral.indexOf(o)+1)%D.oral.length];main.innerHTML=link('#oral','← All oral drills')+heading(o.id,o.question)+timer(1)+`<section class="card reading">${note(o.id)}${reveal(bullets(o.answer)+refs(o.refs))}<h2>Jury follow-up</h2><p>${esc(o.followup)}</p>${rating(o.id)}<div class="toolbar"><button id="random-oral">Random question</button>${link('#oral/'+next.id,'Next question →')}</div></section>`}
else if(route==='legal'){main.innerHTML=heading('06 / Verify','The legal reader','Read the guide, then inspect the full selected provision. Legal review dated 1 November 2026.')+`<details><summary>What to read first</summary><div class="detail-content">${D.legalGuide.map(g=>`<section><h2>${esc(g.law)}</h2><p>${esc(g.priority)} · Read ${esc(g.read)}</p>${bullets(g.points)}${refs(g.refs)}</section>`).join('')}</div></details><details><summary>Application dates and transitions</summary><div class="detail-content">${timelineTable()}<p>Use each provision’s commencement rule. A delayed group of high-risk requirements does not delay every AI Act duty.</p></div></details><div class="toolbar"><select id="law-family" aria-label="Law family"><option value="">All texts</option>${[...new Set(L.map(l=>l.family))].map(f=>`<option>${esc(f)}</option>`).join('')}</select><input id="law-filter" type="search" placeholder="Search provisions and full text" aria-label="Search laws"></div><div id="law-results"></div>`;filterLaws()}
else if(route==='law'){const l=L.find(l=>l.id===id);if(!l)return missing();main.innerHTML=link('#legal','← Legal reader')+heading(l.family+' · '+l.article,l.title,l.version)+`<div class="toolbar">${link(l.url,'Official source ↗')}${l.pdf?link(l.pdf,'Complete official PDF ↗'):''}<button onclick="window.print()">Print provision</button></div>${source(l.language+' · '+l.kind+' · Formatting normalised; consult the official document for layout and footnotes.')}<article class="card law-text">${l.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</article>${note(l.id)}`}
else if(route==='sources')main.innerHTML=heading('07 / Trace','Sources and corrections','Course interpretation and current legal wording have different roles. Keep both visible.')+`<section class="card">${bullets(D.sourceNotes)}</section><h2>Corrections to use when revising</h2>`+D.corrections.map(c=>`<section class="card"><h3>${esc(c.issue)}</h3><p><strong>Course context:</strong> ${esc(c.course)}</p><p>${esc(c.use)}</p>${refs(c.refs)}</section>`).join('')+`<h2>Lecture source map</h2>`+cards(D.modules,m=>`<section class="card"><h3>${esc(m.title)}</h3>${source(m.source)}${source(m.transcript)}</section>`)+`<h2>Original documents</h2>${courseLinks()}`;
else if(route==='downloads')main.innerHTML=heading('08 / Keep','Your offline preparation packs','The documents contain the same course synthesis and answer outlines as the site. Official legal PDFs are included separately.')+`<section class="card feature"><p class="eyebrow">New · typeset with LaTeX</p><h2>Exam preparation pack (6 long + 4 short)</h2><p>Lectures by parts with Vietnamese explanations, the 80-term glossary, the fill-in sentence bank, nine use cases, three mock papers with model answers and the trap-or-truth self-test.</p><p>${link('downloads/exam-prep-pack.pdf','Read PDF')} · ${link('downloads/exam-prep-pack.tex','LaTeX source (.tex)')}</p></section>`+cards([['Final seven-minute video script','rehearsal-dialogue'],['All-role oral defense pack','oral-defense-pack'],['Original scenario and reading paths for all five roles','project-role-reading-pack'],['Legal guide and complete provision appendix','legal-study-pack'],['Compliance Officer oral preparation','compliance-oral-pack'],['Course revision and written-exam practice','exam-study-pack']],([t,f])=>`<section class="card download-card"><h2>${t}</h2><p>${link('downloads/'+f+'.pdf','Read PDF')} · ${link('downloads/'+f+'.docx','Download Word')}</p></section>`)+`<section class="card"><h2>Full official legal texts</h2><p>${link('downloads/official-law-compendium.pdf','Download combined official PDFs')}</p>${bulletsLinks([...new Map(L.filter(l=>l.pdf).map(l=>[l.pdf,[l.pdf,l.family+' · '+l.version]])).values()].concat([['downloads/laws/AI_amendment.pdf','AI Act amendment · Regulation 2026/1744']]))}</section><h2>Course documents</h2>${courseLinks()}<section class="card"><h2>Offline website</h2><p>${link('downloads/atlas-offline.zip','Download website ZIP')}</p><p>Extract the ZIP, run <code>python -m http.server 8000</code> in its folder, then open <code>http://localhost:8000</code>. The JSON reader needs a local web server.</p></section>`;
else if(route==='search'){const term=decodeURIComponent(id||'');const includes=x=>JSON.stringify(x).toLowerCase().includes(term.toLowerCase());const found=[...extraSearch(includes),...D.defense.questions.filter(includes).map(q=>['#defense/'+q.id,q.id+' · '+q.question]),...(includes(D.rehearsal)?[['#rehearsal','Seven-minute rehearsal dialogue']]:[]),...D.roleReading.filter(includes).map(x=>['#roles/'+x.id,'Role · '+x.name]),...(includes(D.scenario)?[['#scenario','Original bank scenario']]:[]),...D.modules.filter(includes).map(x=>['#course/'+x.id,'Module · '+x.title]),...D.questions.filter(includes).map(x=>['#practice/'+x.id,x.id+' · '+x.prompt]),...D.oral.filter(includes).map(x=>['#oral/'+x.id,x.id+' · '+x.question]),...L.filter(includes).map(x=>['#law/'+x.id,x.family+' '+x.article+' · '+x.title])];main.innerHTML=heading('Search',`Results for “${term}”`,found.length+' results')+bulletsLinks(found)}
else if(EXTRA[route])EXTRA[route](id);else missing();window.scrollTo(0,0);}
function missing(){main.innerHTML=heading('Navigation','Choose where to continue','This link does not match a page in the atlas.')+`<div class="toolbar">${link('#home','Overview')}${link('#roles','Prepare your role')}${link('#course','Course modules')}</div>`}
function bulletsLinks(a){return '<ul>'+a.map(([u,t])=>'<li>'+link(u,t)+'</li>').join('')+'</ul>'}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function rubric(){return '<section class="card"><h2>Self-review rubric</h2>'+table(['Criterion','Points','What to look for'],D.rubric)+'<p class="muted">Use this to identify weaknesses, not to predict an official grade.</p></section>'}
function courseLinks(){return bulletsLinks(['Intro-socio-of-AI-5DA06.pdf','Users-of-AI.pdf','EthicsAI_LaborAI_Abel.pdf','Sept 25 - AI regulation.pdf','AI Ethics - Group Project.docx','video_case_studies_guidelines.pdf','example-questions-exam.txt','exam-question-example.txt','exam-question-example-2.txt','exam-example-walkthrough-and-answer.txt'].map(f=>['course/'+encodeURIComponent(f),f]))}
function filterQuestions(){const m=document.querySelector('#module-filter').value,t=document.querySelector('#question-filter').value.toLowerCase();const qs=D.questions.filter(q=>(!m||q.module===m)&&JSON.stringify(q).toLowerCase().includes(t));document.querySelector('#question-list').innerHTML=`<p class="result-count">${qs.length} questions</p>`+cards(qs,q=>`<a class="card title-link" href="#practice/${q.id}"><p class="meta">${q.id} · ${q.format==='short'?'Short · ¼ page':'Long · 1 page'} · ${esc(q.kind)} · ${q.minutes} min</p><h2>${esc(q.prompt)}</h2><span>${esc(state.ratings[q.id]||'Not rated')} · Write →</span></a>`)}
function filterLaws(){const family=document.querySelector('#law-family').value,t=document.querySelector('#law-filter').value.toLowerCase();const laws=L.filter(l=>(!family||l.family===family)&&JSON.stringify(l).toLowerCase().includes(t));document.querySelector('#law-results').innerHTML=`<p class="result-count">${laws.length} provisions / rulings</p><div class="law-list">`+laws.map(l=>`<a class="law-row" href="#law/${l.id}"><span class="law-no">${esc(l.article)}</span><span><strong>${esc(l.title)}</strong><br><span class="meta">${esc(l.family)} · ${esc(l.version)}</span></span><span>→</span></a>`).join('')+'</div>'}
document.addEventListener('input',e=>{if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save()}if(e.target.id==='question-filter')filterQuestions();if(e.target.id==='law-filter')filterLaws()});
document.addEventListener('change',e=>{if(e.target.id==='module-filter')filterQuestions();if(e.target.id==='law-family')filterLaws()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.rate){state.ratings[b.dataset.rate]=b.dataset.value;save();b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b))}if(b.dataset.learn){state.learned[b.dataset.learn]=!state.learned[b.dataset.learn];save();b.textContent=state.learned[b.dataset.learn]?'Mark as not reviewed':'Mark reviewed'}if(b.id==='random-defense')location.hash='defense/'+D.defense.questions[Math.floor(Math.random()*D.defense.questions.length)].id;if(b.id==='random-oral')location.hash='oral/'+D.oral[Math.floor(Math.random()*D.oral.length)].id;if(b.dataset.timer){clearInterval(clockHandle);const end=Date.now()+Number(b.dataset.timer)*60000;b.textContent='Restart timer';clockHandle=setInterval(()=>{const left=Math.max(0,Math.ceil((end-Date.now())/1000));const display=document.querySelector('#timer');if(display)display.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(!left){clearInterval(clockHandle);toast('Practice time finished. Review your reasoning.')}},250)}});
document.querySelector('#global-search').addEventListener('submit',e=>{e.preventDefault();const s=document.querySelector('#search-input').value.trim();if(s)location.hash='search/'+encodeURIComponent(s)});
document.querySelector('#menu-button').onclick=()=>{const n=document.querySelector('#navigation');n.classList.toggle('open');document.querySelector('#menu-button').setAttribute('aria-expanded',String(n.classList.contains('open')))};
document.querySelector('#export-progress').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({format:'ai-ethics-atlas-v1',...state},null,2)],{type:'application/json'}));a.download='ai-ethics-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
document.querySelector('#import-progress').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const x=JSON.parse(await f.text());if(x.format!=='ai-ethics-atlas-v1'||!x.notes||!x.ratings||!x.learned)throw Error();for(const k of ['notes','ratings','learned'])state[k]={...state[k],...x[k]};save();render();toast('Notes imported.')}catch{toast('Could not read this notes file.')}e.target.value=''};
(async()=>{try{const saved=JSON.parse(localStorage.getItem('ai-ethics-atlas-v1'));if(saved)state={...state,...saved}}catch{}try{const responses=await Promise.all([fetch('assets/content.557b00044687.json',{cache:'no-store'}),fetch('assets/laws.bd65db86e002.json',{cache:'no-store'})]);if(responses.some(r=>!r.ok))throw Error();[D,L]=await Promise.all(responses.map(r=>r.json()));window.addEventListener('hashchange',render);render()}catch{main.innerHTML='<h1>The reader could not load.</h1><p>Reload the page. For an offline copy, serve the folder with <code>python -m http.server 8000</code>.</p>'}})();

