function parseRoute(){let raw=location.hash.slice(1).replace(/^\/+|\/+$/g,'');let [route='home',id]=raw.split('/');route=(route||'home').trim().toLowerCase();try{id=id?decodeURIComponent(id).trim():undefined}catch{id=undefined}if(route==='main')route='home';if(route==='role')route='roles';if(['dialogue','script','rehearsal-dialogue'].includes(route))route='rehearsal';if(route==='roles'&&id){const aliases={'computer-scientist':'scientist','computer scientist':'scientist','compliance-officer':'compliance','regulation-compliance-officer':'compliance','ethics-officer':'ethics','ai-ethics-officer':'ethics','cybersecurity':'security','cybersecurity-expert':'security','project-manager':'manager'};id=aliases[id.toLowerCase()]||id.toLowerCase()}return [route,id]}
function breadcrumb(route,id){const group={course:'Exam revision / Course modules',practice:'Exam revision / Practice questions',mocks:'Exam revision / Mock exams',mock:'Exam revision / Mock exam',scenario:'Group project / Original scenario',roles:'Group project / Role preparation',project:'Group project / Recommendations',defense:'Group project / Oral defense',rehearsal:'Group project / Final video script',oral:'Group project / Jury practice',legal:'Reference library / Laws',law:'Reference library / Legal article',sources:'Reference library / Sources',downloads:'Reference library / Downloads',search:'Search results',home:'AI Ethics / Overview'};return group[route]||EXTRA_CRUMB[route]||'AI Ethics'}
function projectSteps(active){return '<div class="project-steps" aria-label="Project preparation steps">'+[['scenario','1. Scenario'],['roles','2. Your role'],['project','3. Recommendations'],['rehearsal','4. Video script'],['oral','5. Oral defense']].map(([r,t])=>`<a href="#${r}" ${r===active?'aria-current="page" class="current"':''}>${t}</a>`).join('')+'</div>'}
document.querySelector('#skip-content').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});

let rehearsalSeconds=420,rehearsalDeadline=0,rehearsalRunning=false;
function paintRehearsalTimer(){const el=document.querySelector('#rehearsal-time');if(el)el.textContent=Math.floor(rehearsalSeconds/60)+':'+String(rehearsalSeconds%60).padStart(2,'0')}
function resetRehearsalTimer(){clearInterval(clockHandle);rehearsalSeconds=420;rehearsalRunning=false;paintRehearsalTimer();const b=document.querySelector('[data-rehearsal-action="start"]');if(b)b.textContent='Start'}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.scriptJump!==undefined)document.querySelector('#script-section-'+b.dataset.scriptJump)?.scrollIntoView({behavior:'smooth',block:'start'});if(b.hasAttribute('data-script-print'))window.print();const action=b.dataset.rehearsalAction;if(action==='reset')resetRehearsalTimer();if(action==='pause'&&rehearsalRunning){rehearsalSeconds=Math.max(0,Math.ceil((rehearsalDeadline-Date.now())/1000));clearInterval(clockHandle);rehearsalRunning=false;paintRehearsalTimer();document.querySelector('[data-rehearsal-action="start"]').textContent='Resume'}if(action==='start'&&!rehearsalRunning&&rehearsalSeconds>0){rehearsalRunning=true;rehearsalDeadline=Date.now()+rehearsalSeconds*1000;clockHandle=setInterval(()=>{rehearsalSeconds=Math.max(0,Math.ceil((rehearsalDeadline-Date.now())/1000));paintRehearsalTimer();if(!rehearsalSeconds){clearInterval(clockHandle);rehearsalRunning=false;toast('Seven minutes finished. Record your timing before the next run.')}},200)}});
document.addEventListener('change',e=>{if(e.target.id==='speaker-focus')applySpeakerFocus()});

function deadlineNotice(){return `<section class="deadline-notice"><strong>Video due 4 November · end of day</strong><span>Presentation and discussion · 6 November 2026</span><p>Keep the video under seven minutes. The discussion explores the details and your overall understanding.</p></section>`}

const SCRIPT_DRAFT_KEY='ai-ethics-script-draft-v1',SCRIPT_SPEAKERS=['PM','CS','Compliance','Security','Ethics'],WORDS_PER_MINUTE=140;
let scriptState={sections:[],source:'published',editing:false,base:'',stale:false},scriptSaveTimer;
function speakerNames(){const m={};SCRIPT_SPEAKERS.forEach(k=>m[k]=k);D.rehearsal.sections.forEach(s=>s.turns.forEach(t=>{if(m[t.speaker]===t.speaker&&t.name)m[t.speaker]=t.name}));return m}
function publishedScript(){return D.rehearsal.sections.map(s=>({time:s.time,title:s.title,cue:s.cue.replace(/^Cue:\s*/,''),turns:s.turns.map(t=>({speaker:t.speaker,text:t.text}))}))}
function scriptHash(sections){const s=JSON.stringify(sections);let h=5381;for(let i=0;i<s.length;i++)h=(Math.imul(h,33)^s.charCodeAt(i))>>>0;return h.toString(36)}
function packScript(sections){return sections.map(s=>[s.time,s.title,s.cue,s.turns.map(t=>[t.speaker,t.text])])}
// Shared links and stored drafts are untrusted input: accept only the expected shape and known speakers.
function unpackScript(x){const str=(v,max)=>{if(typeof v!=='string'||v.length>max)throw Error('invalid');return v};if(!Array.isArray(x)||!x.length||x.length>40)throw Error('invalid');return x.map(s=>{if(!Array.isArray(s)||s.length!==4||!Array.isArray(s[3])||s[3].length>200)throw Error('invalid');return {time:str(s[0],40),title:str(s[1],200),cue:str(s[2],1000),turns:s[3].map(t=>{if(!Array.isArray(t)||!SCRIPT_SPEAKERS.includes(t[0]))throw Error('invalid');return {speaker:t[0],text:str(t[1],4000)}})}})}
const base64url={encode:bytes=>{let s='';bytes.forEach(b=>s+=String.fromCharCode(b));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')},decode:text=>Uint8Array.from(atob(text.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))};
const streamBytes=async(bytes,stream)=>new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(stream)).arrayBuffer());
async function encodeScript(sections){const bytes=new TextEncoder().encode(JSON.stringify(packScript(sections)));if('CompressionStream' in window)return 'z1.'+base64url.encode(await streamBytes(bytes,new CompressionStream('deflate-raw')));return 'j1.'+base64url.encode(bytes)}
async function decodeScript(code){let bytes=base64url.decode(code.slice(3));if(code.startsWith('z1.'))bytes=await streamBytes(bytes,new DecompressionStream('deflate-raw'));else if(!code.startsWith('j1.'))throw Error('format');return unpackScript(JSON.parse(new TextDecoder().decode(bytes)))}
function loadScriptDraft(){try{const d=JSON.parse(localStorage.getItem(SCRIPT_DRAFT_KEY));return d?{base:String(d.base||''),sections:unpackScript(packScript(d.sections))}:null}catch{return null}}
function scriptWords(){return scriptState.sections.reduce((n,s)=>n+s.turns.reduce((m,t)=>m+t.text.trim().split(/\s+/).filter(Boolean).length,0),0)}
async function renderRehearsal(id){
 const published=publishedScript(),base=scriptHash(published);let problem='';
 scriptState={sections:published,source:'published',editing:false,base,stale:false};
 if(id&&/^[zj]1\./.test(id)){try{scriptState.sections=await decodeScript(id);scriptState.source='link'}catch{problem='This share link is incomplete or damaged, so the published script is shown instead. Ask for the link again.'}}
 else{const draft=loadScriptDraft();if(draft){scriptState.sections=draft.sections;scriptState.source='draft';scriptState.stale=draft.base!==base}}
 if(parseRoute()[0]!=='rehearsal')return;
 const names=speakerNames();
 main.innerHTML=heading('Group project / Step 4','Final seven-minute video script','A complete committee dialogue: the bank’s difficulties, the disagreements and the final recommendation.')+projectSteps('rehearsal')+deadlineNotice()+`<p class="source">Target 6:40 including pauses; confirm with a recorded run. ${link('downloads/rehearsal-dialogue-original.txt','Original supplied dialogue (archive)')}</p><div class="rehearsal-layout"><aside class="rehearsal-controls card"><h2>Rehearse</h2><p class="timer" id="rehearsal-time" role="timer" aria-label="Time remaining">7:00</p><div class="timer-actions"><button data-rehearsal-action="start">Start</button><button data-rehearsal-action="pause">Pause</button><button data-rehearsal-action="reset">Reset</button></div><label for="speaker-focus">Highlight my lines</label><select id="speaker-focus"><option value="">All speakers</option>${SCRIPT_SPEAKERS.map(k=>`<option value="${k}">${k} (${esc(names[k])})</option>`).join('')}</select><p class="source">Other speakers stay visible for context.</p><h3>Jump to a section</h3><div class="script-jumps" id="script-jumps"></div><p class="source">6:40–7:00 · Buffer</p><p>Published version: ${link('downloads/rehearsal-dialogue.pdf','PDF')} · ${link('downloads/rehearsal-dialogue.docx','Word')} · ${link(D.rehearsal.download,'Plain text')}</p><button data-script-print>Print dialogue</button></aside><div class="script-body"><section class="card script-editor"><h2>Edit and share the script</h2><p>Click <strong>Edit script</strong> to change any line, the speaker or the stage directions, and to add, move or delete lines. Changes save automatically in this browser. Use <strong>Copy share link</strong> to send your version to the group: the link contains the whole edited script, so anyone who opens it sees your edits.</p><div class="script-editor-bar"><button class="primary" data-script-mode>Edit script</button><button data-script-share>Copy share link</button><button data-script-download>Download edited .txt</button><button data-script-reset>Reset to published</button></div><input id="script-share-output" class="share-output" readonly hidden aria-label="Share link"><p class="script-status" id="script-status" role="status"></p>${problem?`<p class="script-status warn">${esc(problem)}</p>`:''}</section><section class="callout"><p>${esc(D.rehearsal.intro)}</p><p class="source">${esc(D.rehearsal.source)}</p></section><div id="script-sections"></div><section class="card"><h2>Delivery notes</h2>${bullets(D.rehearsal.notes)}</section><section class="card rehearsal-notes"><h2>Notes from your run</h2>${note('rehearsal')}<p>${link('#oral','Next: jury practice →')}</p></section></div></div>`;
 paintScript();resetRehearsalTimer()}
function scriptTurnHtml(t,i,j,names){
 if(!scriptState.editing)return `<article class="script-turn" data-speaker="${esc(t.speaker)}"><h3>${esc(t.speaker)} (${esc(names[t.speaker])})</h3><p>${esc(t.text)}</p></article>`;
 const at=`data-s="${i}" data-t="${j}"`;
 return `<article class="script-turn editing" data-speaker="${esc(t.speaker)}"><div class="turn-tools"><select data-edit="speaker" ${at} aria-label="Speaker">${SCRIPT_SPEAKERS.map(k=>`<option value="${k}"${k===t.speaker?' selected':''}>${k} (${esc(names[k])})</option>`).join('')}</select><span class="turn-buttons"><button data-script-edit="up" ${at} aria-label="Move line up" title="Move up">↑</button><button data-script-edit="down" ${at} aria-label="Move line down" title="Move down">↓</button><button data-script-edit="add" data-s="${i}" data-t="${j+1}">+ Line below</button><button data-script-edit="delete" ${at}>Delete</button></span></div><textarea data-edit="text" ${at} rows="3" aria-label="Line text">${esc(t.text)}</textarea></article>`}
function paintScript(){
 const box=document.querySelector('#script-sections');if(!box)return;const names=speakerNames(),editing=scriptState.editing;
 box.innerHTML=scriptState.sections.map((s,i)=>`<section class="script-section" id="script-section-${i}">`+(editing?`<div class="script-section-heading edit-heading"><input class="edit-time" data-edit="time" data-s="${i}" value="${esc(s.time)}" aria-label="Section time"><input class="edit-title" data-edit="title" data-s="${i}" value="${esc(s.title)}" aria-label="Section title"><button data-script-edit="delsection" data-s="${i}">Delete section</button></div><label class="edit-cue-label">Stage direction (not spoken)<input class="edit-cue" data-edit="cue" data-s="${i}" value="${esc(s.cue)}"></label>`:`<div class="script-section-heading"><span class="tag">${esc(s.time)}</span><h2>${esc(s.title)}</h2></div>${s.cue?`<p class="script-cue"><em>Cue: ${esc(s.cue)}</em></p>`:''}`)+s.turns.map((t,j)=>scriptTurnHtml(t,i,j,names)).join('')+(editing?`<button class="add-line" data-script-edit="add" data-s="${i}" data-t="${s.turns.length}">+ Add a line to this section</button>`:'')+'</section>').join('')+(editing?'<button class="add-line" data-script-edit="addsection">+ Add a section</button>':'');
 box.querySelectorAll('textarea').forEach(fitTextarea);
 const jumps=document.querySelector('#script-jumps');if(jumps)jumps.innerHTML=scriptState.sections.map((s,i)=>`<button data-script-jump="${i}">${esc(s.time)} · ${esc(s.title)}</button>`).join('');
 const mode=document.querySelector('[data-script-mode]');if(mode)mode.textContent=editing?'Finish editing':'Edit script';
 paintScriptStatus();applySpeakerFocus()}
function fitTextarea(t){t.style.height='auto';t.style.height=t.scrollHeight+2+'px'}
window.addEventListener('resize',()=>document.querySelectorAll('.script-turn textarea').forEach(fitTextarea));
function paintScriptStatus(){const el=document.querySelector('#script-status');if(!el)return;const words=scriptWords(),sec=Math.round(words/WORDS_PER_MINUTE*60),label={published:'Published version',draft:'Your edited version, saved in this browser',link:'Shared version opened from a link. Editing it saves a copy in this browser.'}[scriptState.source];
 el.textContent=`${label} · ${scriptState.sections.reduce((n,s)=>n+s.turns.length,0)} lines · ${words} spoken words · about ${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')} at ${WORDS_PER_MINUTE} words per minute`+(scriptState.stale&&scriptState.source==='draft'?'. The published script has changed since this draft was saved; reset to see the new version.':'');el.classList.toggle('warn',scriptState.stale&&scriptState.source==='draft')}
function applySpeakerFocus(){const v=document.querySelector('#speaker-focus')?.value||'';document.querySelectorAll('.script-turn').forEach(t=>t.classList.toggle('speaker-highlight',!!v&&v.split(',').includes(t.dataset.speaker)))}
function scheduleScriptSave(){if(scriptState.source!=='draft'){scriptState.source='draft';scriptState.stale=false}paintScriptStatus();clearTimeout(scriptSaveTimer);scriptSaveTimer=setTimeout(persistScript,400)}
async function persistScript(){clearTimeout(scriptSaveTimer);try{localStorage.setItem(SCRIPT_DRAFT_KEY,JSON.stringify({base:scriptState.base,saved:new Date().toISOString(),sections:scriptState.sections}))}catch{toast('Browser storage unavailable. Use Copy share link or Download to keep your edits.')}const code=await encodeScript(scriptState.sections);if(parseRoute()[0]==='rehearsal')history.replaceState(null,'','#rehearsal/'+code);return location.href}
function scriptAsText(){const r=D.rehearsal,names=speakerNames(),flat=s=>s.replace(/\s*\n\s*/g,' ').trim();return [r.title,r.intro,...scriptState.sections.flatMap(s=>[flat(s.time)+' '+flat(s.title),'Cue: '+flat(s.cue),...s.turns.map(t=>`${t.speaker} (${names[t.speaker]}): ${flat(t.text)}`)]),'Delivery notes',...r.notes].join('\n')+'\n'}
function editScript(b){
 const S=scriptState.sections,i=+b.dataset.s,j=+b.dataset.t,action=b.dataset.scriptEdit;let focus=null;
 if(action==='add'){const prev=S[i].turns[j-1]?.speaker,next=SCRIPT_SPEAKERS.find(k=>k!==prev)||'PM';S[i].turns.splice(j,0,{speaker:next,text:''});focus=[i,j]}
 if(action==='delete'){if(S[i].turns[j].text.trim()&&!confirm('Delete this line?'))return;S[i].turns.splice(j,1)}
 if(action==='up'){if(j>0)[S[i].turns[j-1],S[i].turns[j]]=[S[i].turns[j],S[i].turns[j-1]];else if(i>0)S[i-1].turns.push(S[i].turns.shift());else return}
 if(action==='down'){if(j<S[i].turns.length-1)[S[i].turns[j+1],S[i].turns[j]]=[S[i].turns[j],S[i].turns[j+1]];else if(i<S.length-1)S[i+1].turns.unshift(S[i].turns.pop());else return}
 if(action==='addsection'){S.push({time:'',title:'New section',cue:'',turns:[{speaker:'PM',text:''}]});focus=[S.length-1,0]}
 if(action==='delsection'){if(S.length===1)return toast('The script needs at least one section.');if(S[i].turns.length&&!confirm('Delete this section and its lines?'))return;S.splice(i,1)}
 paintScript();scheduleScriptSave();if(focus)document.querySelector(`textarea[data-s="${focus[0]}"][data-t="${focus[1]}"]`)?.focus()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!D)return;
 if(b.dataset.scriptEdit!==undefined)return editScript(b);
 if(b.hasAttribute('data-script-mode')){scriptState.editing=!scriptState.editing;paintScript();if(!scriptState.editing)await persistScript();return}
 if(b.hasAttribute('data-script-share')){const url=await persistScript(),out=document.querySelector('#script-share-output');out.hidden=false;out.value=url;out.select();try{await navigator.clipboard.writeText(url);toast('Share link copied. Paste it to your group.')}catch{toast('Copy the selected link to share it.')}return}
 if(b.hasAttribute('data-script-download')){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([scriptAsText()],{type:'text/plain;charset=utf-8'}));a.download='rehearsal-dialogue-edited.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return}
 if(b.hasAttribute('data-script-reset')){if(!confirm('Discard the edited version in this browser and show the published script?'))return;clearTimeout(scriptSaveTimer);try{localStorage.removeItem(SCRIPT_DRAFT_KEY)}catch{}history.replaceState(null,'','#rehearsal');scriptState={...scriptState,sections:publishedScript(),source:'published',stale:false};const out=document.querySelector('#script-share-output');if(out)out.hidden=true;paintScript();toast('Showing the published script.')}});
document.addEventListener('input',e=>{const el=e.target.closest('[data-edit]');if(!el||!D||!scriptState.editing)return;const s=scriptState.sections[+el.dataset.s];if(!s)return;const field=el.dataset.edit;
 if(field==='text'){s.turns[+el.dataset.t].text=el.value;fitTextarea(el)}
 else if(field==='speaker'){s.turns[+el.dataset.t].speaker=el.value;el.closest('.script-turn').dataset.speaker=el.value;applySpeakerFocus()}
 else s[field]=el.value;
 if(field==='time'||field==='title'){const j=document.querySelector(`[data-script-jump="${el.dataset.s}"]`);if(j)j.textContent=s.time+' · '+s.title}
 scheduleScriptSave()});

