const PREF_KEY='ai-ethics-atlas-prefs-v1';
let prefs={vi:true,recall:false,best:{},known:{}};
try{const p=JSON.parse(localStorage.getItem(PREF_KEY));if(p)prefs={...prefs,...p}}catch{}
function savePrefs(){try{localStorage.setItem(PREF_KEY,JSON.stringify(prefs))}catch{}}
const LECT=id=>D.lectures.find(l=>l.id===id);
const lectTag=id=>{const l=LECT(id);return l?`<a class="tag" href="#lecture/${l.id}">${esc(l.id)}</a>`:esc(id)};
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const slotHtml=(t,fill)=>esc(t).replace(/\{([A-Z]+)\}/g,(m,k)=>fill&&fill[k]?`<mark class="filled" title="${esc(D.kit.slots[k]||k)}">${esc(fill[k])}</mark>`:`<span class="slot" title="${esc(D.kit.slots[k]||k)}">${esc(k)}</span>`);
const viToggle=()=>`<div class="toolbar prefs"><button data-pref="vi" class="${prefs.vi?'selected':''}">${prefs.vi?'Tiếng Việt: on':'Tiếng Việt: off'}</button><button data-pref="recall" class="${prefs.recall?'selected':''}">${prefs.recall?'Recall mode: on — tap an idea to reveal':'Recall mode: off'}</button><button onclick="window.print()">Print this page</button></div>`;
function applyPrefs(){main.classList.toggle('hide-vi',!prefs.vi);main.classList.toggle('recall',prefs.recall)}
function ideaHtml(i,n){const en=i.en.startsWith(i.key)?`<strong>${esc(i.key)}</strong>${esc(i.en.slice(i.key.length))}`:`<strong>${esc(i.key)}</strong> — ${esc(i.en)}`;return `<li class="idea" tabindex="0"><span class="idea-num">${n}.</span><div><p class="idea-key">${esc(i.key)}</p><div class="idea-body"><p class="idea-en">${en}</p><p class="vi" lang="vi">${esc(i.vi)}</p>${i.tip?`<p class="idea-tip">Exam: ${esc(i.tip)}</p>`:''}</div></div></li>`}

