function examBanner(){return `<section class="card feature exam-banner"><p class="eyebrow">Table exam · 10 questions</p><h2>6 long answers (1 A4 page each) + 4 short answers (1 page total)</h2><p>Learn each lecture as numbered ideas, master the glossary, then write with the 5-block skeleton and the fill-in sentence bank.</p><div class="toolbar">${link('#lectures','1. Lectures by parts')}${link('#glossary','2. Glossary table')}${link('#kit','3. Writing kit')}${link('#usecases','4. Use-case bank')}${link('#exams','5. 10-question mocks')}${link('#games','6. Concept games')}</div></section>`}

const EXTRA={
 lectures(){main.innerHTML=heading('Exam prep / Learn','Lectures by parts','Each lecture is split into parts; each part lists numbered main ideas in an “X is Y” form with a Vietnamese explanation. Turn on recall mode to test yourself.')+cards(D.lectures,l=>`<a class="card title-link" href="#lecture/${l.id}"><p class="meta">${l.id} · ${esc(l.teacher)} · ${l.parts.length} parts · ${l.parts.reduce((n,p)=>n+p.ideas.length,0)} ideas</p><h2>${esc(l.title)}</h2><p>${esc(l.why)}</p><span>Open →</span></a>`)},
 lecture(id){const l=LECT(id);if(!l)return missing();const i=D.lectures.indexOf(l),next=D.lectures[(i+1)%D.lectures.length];let n=0;
  main.innerHTML=link('#lectures','← All lectures')+heading(l.id+' · '+l.teacher,l.title,l.why)+source('Slides: '+l.slides+' · Recordings: '+l.sessions)+viToggle()+`<nav class="part-jumps">${l.parts.map((p,k)=>`<button data-jump="part-${k}">${esc(p.title.split('—')[0].trim())}</button>`).join('')}</nav>`+l.parts.map((p,k)=>{n=0;return `<section class="card part" id="part-${k}"><h2>${esc(p.title)}</h2><ol class="ideas">${p.ideas.map(x=>ideaHtml(x,++n)).join('')}</ol></section>`}).join('')+`<section class="card"><h2>Terms from this lecture</h2>${glossTable(D.glossary.filter(g=>g.lecture===l.id))}</section><div class="toolbar">${link('#game/flash/'+l.id,'Flashcards for '+l.id+' →')}${link('#game/quiz/'+l.id,'Quiz on '+l.id+' →')}${link('#lecture/'+next.id,'Next lecture: '+next.id+' →')}</div>`;applyPrefs()},
 glossary(){main.innerHTML=heading('Exam prep / Remember','Consolidated glossary',D.glossary.length+' terms from all lectures: definition, Vietnamese explanation and when to use it in an answer.')+`<div class="toolbar"><input id="gloss-filter" type="search" placeholder="Filter terms…" aria-label="Filter terms"><select id="gloss-lecture" aria-label="Filter by lecture"><option value="">All lectures</option>${D.lectures.map(l=>`<option value="${l.id}">${l.id} · ${esc(l.title)}</option>`).join('')}</select><button onclick="window.print()">Print</button></div><div id="gloss-out"></div>`;filterGloss()},
 kit(id){const uc=D.usecases.find(u=>u.id===id),k=D.kit,f=k.format;
  main.innerHTML=heading('Exam prep / Write','Exam writing kit',f.summary)+
  `<section class="card"><h2>Page and time budget</h2>${table(['Question','Length','Structure','What earns points'],f.rows)}${table(f.time[0],f.time.slice(1))}<h3>Order of work</h3>${bullets(f.order)}</section>`+
  `<section class="callout"><h3>What the teachers said about the exam</h3>${bullets(f.teacher_hints)}</section>`+
  `<div class="grid"><section class="card"><h2>Long answer = 1 page, 5 blocks</h2><ol class="blocks">${k.long.map(b=>`<li><span class="block-label">${esc(b.label)}</span><div><strong>${esc(b.title)}</strong><p>${esc(b.en)}</p><p class="vi" lang="vi">${esc(b.vi)}</p></div></li>`).join('')}</ol><p class="muted">Each argument block = <strong>Claim → Concept (author) → Mechanism in this case → Measure</strong>.</p></section><section class="card"><h2>Short answer = ¼ page, D-N-E</h2><ol class="blocks">${k.short.map(b=>`<li><span class="block-label">${esc(b.label)}</span><div><strong>${esc(b.title)}</strong><p>${esc(b.en)}</p><p class="vi" lang="vi">${esc(b.vi)}</p></div></li>`).join('')}</ol><p class="muted">Template: “<em>X is … . Three examples are (1) …, (2) …, (3) … . For instance, … (author, year).</em>”</p></section></div>`+
  `<section class="card" id="sentence-bank"><h2>Fill-in sentence bank</h2><p>Words in <span class="slot">CAPITALS</span> are slots. Choose a use case and every slot fills with case-specific wording (highlighted) — then rehearse the sentences aloud or copy them.</p><div class="toolbar"><select id="kit-usecase" aria-label="Plug in a use case"><option value="">— Show empty slots —</option>${D.usecases.map(u=>`<option value="${u.id}" ${uc&&uc.id===u.id?'selected':''}>${esc(u.title)}</option>`).join('')}</select>${uc?link('#usecases','About this use case'):''}</div>${uc?`<p class="callout">${esc(uc.brief)}</p>`:''}${viToggle()}${k.templates.map(g=>`<h3>${esc(g.title)}</h3><ol class="templates">${g.items.map(t=>`<li><p>${slotHtml(t.en,uc&&uc.slots)}</p><p class="vi" lang="vi">${esc(t.vi)}</p></li>`).join('')}</ol>`).join('')}</section>`+
  `<section class="card"><h2>Slot legend</h2>${table(['Slot','Means'],Object.entries(k.slots))}</section>`;applyPrefs()},
 usecases(){main.innerHTML=heading('Exam prep / Adapt','Use-case bank','Nine typical exam scenarios with ready-made slot values and the course angles to use. Open one in the writing kit to generate rehearsal sentences.')+D.usecases.map(u=>`<section class="card usecase"><p class="meta">${u.sample?'<span class="tag gold">Official sample topic</span>':''}</p><h2>${esc(u.title)}</h2><p>${esc(u.brief)}</p><div class="split"><div>${table(['Slot','Value for this case'],Object.entries(u.slots).map(([k,v])=>[k,v]))}</div><aside class="aside-card"><h3>Angles to use</h3>${bullets(u.angles)}${link('#kit/'+u.id,'Plug into the sentence bank →')}</aside></div></section>`).join('')},
 exams(){main.innerHTML=heading('Exam prep / Rehearse','Mocks in the real format','Each paper: 4 short questions (one page in total) + 6 long questions (one page each). Paper A has fully written model answers to the official sample questions; B and C give block-by-block outlines.')+cards(D.examMocks,m=>`<a class="card title-link" href="#exam/${m.id}"><p class="meta">Paper ${m.id} · 4 short + 6 long</p><h2>${esc(m.title)}</h2><span>Begin →</span></a>`)+`<section class="card"><h2>All 40 earlier practice questions</h2><p>They are now tagged <strong>Long · 1 page</strong> or <strong>Short · ¼ page</strong>. ${link('#practice','Open practice questions →')}</p></section>`},
 exam(id){const m=D.examMocks.find(m=>m.id===id);if(!m)return missing();const qs=[...m.questions.filter(q=>q.kind==='short'),...m.questions.filter(q=>q.kind==='long')];
  main.innerHTML=link('#exams','← All papers')+heading('Paper '+m.id,m.title,'Short questions first, then long ones. Write in the box (or on paper), then reveal the model answer.')+`<div class="toolbar"><span class="timer" id="timer">120:00</span><button data-timer="120">Start 2-hour timer</button><button data-timer="180">Start 3-hour timer</button></div>`+
  qs.map((q,i)=>{const qid='EX'+m.id+(i+1);const ans=q.kind==='short'?`<p>${esc(q.answer)}</p><p class="muted">${q.answer.split(/\s+/).length} words — about a quarter page.</p>`:`<ol class="blocks">${q.plan.map(b=>`<li><span class="block-label">${esc(b.label)}</span><p>${esc(b.text)}</p></li>`).join('')}</ol><p class="muted">${q.plan.reduce((n,b)=>n+b.text.split(/\s+/).length,0)} words${m.id==='A'?' — about one handwritten page.':' in outline — expand each block to ~60 words.'}</p>`;
   return `<article class="card"><p class="meta">Q${i+1} · ${q.kind==='long'?'<span class="tag gold">Long · 1 A4 page</span>':'<span class="tag">Short · ¼ page</span>'} ${q.lectures.map(lectTag).join('')}</p><h2>${esc(q.prompt)}</h2>${note(qid)}<details><summary>Reveal model answer</summary><div class="detail-content">${ans}</div></details>${rating(qid)}</article>`}).join('')},
 games(){main.innerHTML=heading('Exam prep / Play','Concept games','Four short games built from all '+D.glossary.length+' glossary terms and '+D.lectures.reduce((n,l)=>n+l.parts.reduce((m,p)=>m+p.ideas.length,0),0)+' lecture ideas. Best scores are kept in this browser.')+`<div class="grid">${[
  ['flash','Flashcards','Flip a card, say the definition aloud, mark “Got it” or “Again”. Cards you know drop out of the deck.'],
  ['match','Match race','Pair 6 terms with their definitions as fast as you can. Wrong pairs cost 3 seconds.'],
  ['quiz','Concept quiz','Read a definition (English or Vietnamese) and pick the right concept from 4. Build a streak.'],
  ['trap','Trap or truth?','Exam traps the teachers warned about. Decide true or false, then read why.']].map(([k,t,d])=>`<a class="card title-link game-card" href="#game/${k}"><p class="meta">${prefs.best[k]!=null?'Best: '+esc(prefs.best[k]):'New'}</p><h2>${t}</h2><p>${d}</p><span>Play →</span></a>`).join('')}</div>`},
 game(id){const [mode,lec]=(location.hash.split('/').slice(1));GAMES[mode]?GAMES[mode](lec&&LECT(lec)?lec:''):missing()}
};

function glossTable(rows){return '<div class="table-wrap"><table class="gloss"><thead><tr><th>Term</th><th>Definition</th><th class="vi">Tiếng Việt</th><th>Use it when</th><th>Lecture</th></tr></thead><tbody>'+rows.map(g=>`<tr><td><strong>${esc(g.term)}</strong></td><td>${esc(g.en)}</td><td class="vi" lang="vi">${esc(g.vi)}</td><td>${esc(g.use)}</td><td>${lectTag(g.lecture)}</td></tr>`).join('')+'</tbody></table></div>'}
function filterGloss(){const t=(document.querySelector('#gloss-filter')?.value||'').toLowerCase(),l=document.querySelector('#gloss-lecture')?.value||'';const rows=D.glossary.filter(g=>(!l||g.lecture===l)&&JSON.stringify(g).toLowerCase().includes(t));document.querySelector('#gloss-out').innerHTML=`<p class="result-count">${rows.length} terms</p>`+glossTable(rows)}

// ---- Games ----
function deck(lec){const g=D.glossary.filter(x=>!lec||x.lecture===lec).map(x=>({id:'g:'+x.term,term:x.term,def:x.en,vi:x.vi,lec:x.lecture}));const ideas=D.lectures.filter(l=>!lec||l.id===lec).flatMap(l=>l.parts.flatMap(p=>p.ideas.map(i=>({id:'i:'+l.id+':'+i.key,term:i.key,def:i.en,vi:i.vi,lec:l.id}))));return [...g,...ideas]}
const mask=(def,term)=>{let s=def;term.replace(/[“”"().]/g,'').split(/[\s/]+/).filter(w=>w.length>3).forEach(w=>{s=s.replace(new RegExp(w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),'▢▢▢')});return s};
function lecturePicker(mode,lec){return `<div class="toolbar"><select data-game-lecture="${mode}" aria-label="Choose lecture"><option value="">All lectures</option>${D.lectures.map(l=>`<option value="${l.id}" ${l.id===lec?'selected':''}>${l.id} · ${esc(l.title)}</option>`).join('')}</select>${link('#games','← All games')}</div>`}
function setBest(k,v,better){const old=prefs.best[k];if(old==null||better(v,old)){prefs.best[k]=v;savePrefs();return true}return false}
let G={};
const GAMES={
 flash(lec){const all=deck(lec);G={mode:'flash',lec,queue:shuffle(all.filter(c=>!prefs.known[c.id])),total:all.length,flipped:false};
  if(!G.queue.length){main.innerHTML=heading('Game','Flashcards','You know every card in this deck. 🎉')+lecturePicker('flash',lec)+`<button data-flash="reset">Reset this deck</button>`;return}paintFlash()},
 match(lec){const pool=shuffle(deck(lec).filter(c=>c.id.startsWith('g:'))).slice(0,6);G={mode:'match',lec,pool,left:shuffle(pool),right:shuffle(pool),sel:null,done:new Set(),start:Date.now(),penalty:0};paintMatch();clearInterval(clockHandle);clockHandle=setInterval(()=>{const el=document.querySelector('#match-time');if(el)el.textContent=matchTime()+' s'},250)},
 quiz(lec){G={mode:'quiz',lec,pool:deck(lec),round:0,score:0,streak:0,best:0,answered:false};nextQuiz()},
 trap(){G={mode:'trap',items:shuffle(TRAPS),i:0,score:0,answered:false};paintTrap()}
};
function paintFlash(){const c=G.queue[0],known=G.total-G.queue.length;main.innerHTML=heading('Game · Flashcards',`${known} / ${G.total} known`,'Say the definition aloud before you flip.')+lecturePicker('flash',G.lec)+`<div class="progressbar"><div style="width:${Math.round(known/G.total*100)}%"></div></div><button class="flashcard ${G.flipped?'flipped':''}" data-flash="flip" aria-live="polite"><span class="tag">${esc(c.lec)}</span><strong class="fc-term">${esc(c.term)}</strong>${G.flipped?`<span class="fc-def">${esc(c.def)}</span><span class="fc-vi vi" lang="vi">${esc(c.vi)}</span>`:'<span class="muted">Tap to flip</span>'}</button><div class="toolbar center"><button data-flash="again">↺ Again</button><button class="primary" data-flash="known">✓ Got it</button></div>`;applyPrefs()}
const matchTime=()=>((Date.now()-G.start)/1000+G.penalty).toFixed(1);
function paintMatch(){const btn=(c,side)=>`<button class="match-item ${G.done.has(c.id)?'done':''} ${G.sel&&G.sel.side===side&&G.sel.id===c.id?'selected':''}" data-match="${side}" data-id="${esc(c.id)}" ${G.done.has(c.id)?'disabled':''}>${esc(side==='l'?c.term:mask(c.def,c.term))}</button>`;
 main.innerHTML=heading('Game · Match race','Pair each term with its definition','Pick a term, then its definition. Definitions hide the term’s own words (▢▢▢). Wrong pair = +3 s.')+lecturePicker('match',G.lec)+`<p class="timer" id="match-time">${matchTime()} s</p><div class="match-grid"><div>${G.left.map(c=>btn(c,'l')).join('')}</div><div>${G.right.map(c=>btn(c,'r')).join('')}</div></div>`}
function finishMatch(){clearInterval(clockHandle);const t=Number(matchTime()),rec=setBest('match',t,(a,b)=>a<b);main.innerHTML=heading('Game · Match race',`Done in ${t} s`,rec?'New personal best! 🏆':'Best: '+prefs.best.match+' s')+`<section class="card">${table(['Term','Definition'],G.pool.map(c=>[c.term,c.def]))}</section><div class="toolbar"><button class="primary" data-replay="match">Play again</button>${link('#games','All games')}</div>`}
function nextQuiz(){if(G.round>=10){const rec=setBest('quiz',G.score,(a,b)=>a>b);main.innerHTML=heading('Game · Concept quiz',`Score ${G.score} / 10`,(rec?'New best! 🏆 ':'')+'Longest streak: '+G.best)+`<div class="toolbar"><button class="primary" data-replay="quiz">Play again</button>${link('#games','All games')}</div>`;return}
 const pool=G.pool,ans=pool[Math.floor(Math.random()*pool.length)],useVi=Math.random()<.4;const others=shuffle(pool.filter(c=>c.term!==ans.term&&c.lec===ans.lec)).concat(shuffle(pool.filter(c=>c.lec!==ans.lec))).filter((c,i,a)=>a.findIndex(x=>x.term===c.term)===i).slice(0,3);
 G.cur={ans,opts:shuffle([ans,...others]),useVi};G.answered=false;G.round++;paintQuiz()}
function paintQuiz(){const {ans,opts,useVi}=G.cur;main.innerHTML=heading('Game · Concept quiz',`Question ${G.round} / 10`,`Score ${G.score} · Streak ${G.streak}${G.streak>=3?' 🔥':''}`)+lecturePicker('quiz',G.lec)+`<section class="card quiz-q"><p class="meta">${useVi?'Tiếng Việt':'English'} · ${esc(ans.lec)}</p><p class="quiz-def" ${useVi?'lang="vi"':''}>${esc(mask(useVi?viClue(ans.vi):ans.def,ans.term))}</p></section><div class="quiz-opts">${opts.map(o=>`<button data-quiz="${esc(o.term)}" class="${G.answered?(o.term===ans.term?'right':(o.term===G.picked?'wrong':'')):''}" ${G.answered?'disabled':''}>${esc(o.term)}</button>`).join('')}</div>${G.answered?`<section class="card"><p><strong>${esc(ans.term)}</strong> — ${esc(ans.def)}</p><p class="vi" lang="vi">${esc(ans.vi)}</p><button class="primary" data-quiz-next>Next →</button></section>`:''}`}
const TRAPS=[
 ['A human adviser signs every credit refusal, so the decision is not automated under Article 22 GDPR.',false,'SCHUFA (CJEU 2023): if the score decisively drives the decision, it is an automated decision. Human signature ≠ meaningful review.'],
 ['Every AI system used by a public body is high-risk under the AI Act.',false,'Classification depends on the intended purpose (Annex I/III, Art. 5, Art. 50), not on who uses it. Public bodies do have extra duties, e.g. the FRIA.'],
 ['Pseudonymised data (names replaced by codes) are still personal data.',true,'Re-identification remains possible, so the GDPR still applies. Only true anonymisation leaves its scope.'],
 ['Open-weight GPAI models have no AI Act obligations.',false,'The open-source exemption covers documentation duties only; the copyright policy and the training-content summary still apply, and systemic-risk models get no exemption.'],
 ['Real-time remote biometric identification in public spaces for law enforcement is prohibited, with narrow exceptions.',true,'Art. 5 AI Act: exceptions such as finding missing persons, abduction, trafficking, terrorist threats or suspects of serious crimes.'],
 ['Emotion recognition used to monitor employees at work is prohibited.',true,'Art. 5 prohibits emotion inference in the workplace and in education (except medical or safety reasons).'],
 ['Symbolic AI was simply replaced by neural AI.',false,'The linear-history preconception: symbolic, connectionist and neuro-symbolic approaches coexist (Cardon et al. 2018; Gargiulo et al. 2023).'],
 ['Data work disappears once the model is trained.',false,'Verification “never goes away” (Tubaro 2020); see the Cour de cassation’s permanent annotation team.'],
 ['A piece rate of $0.10 per task tells you the worker’s hourly wage.',false,'Unpaid search, rejections and returns make effective pay much lower (MTurk median ≈ $1.77/h).'],
 ['Ethics charters are legally binding.',false,'They are soft law — but they can harden when a company publicly commits to them or when they are incorporated into binding texts.'],
 ['A fairness metric is a normative choice about which disparities matter.',true,'Choosing a metric encodes values; intersectionality is rarely captured. The mulching paper shows FAT cannot rescue an unacceptable purpose.'],
 ['Consent is the only lawful basis for processing personal data.',false,'Art. 6 lists six bases (consent, contract, legal obligation, vital interest, public task, legitimate interest) — one basis AND all the principles.'],
 ['Under the AI Act, an AI system must be autonomous and adaptive.',false,'Autonomy and adaptiveness are optional; the key criterion is inference.'],
 ['Media visibility of a risk shows how large that risk is.',false,'Attention is a limited and political resource; media salience ≠ risk magnitude (e.g. super-intelligence coverage).'],
 ['A GPAI model is presumed to have high-impact capabilities above 10^25 FLOPs of training compute.',true,'Or it can be designated by the Commission, including after a qualified alert from the scientific panel.'],
 ['A scientific independent panel advising the Commission may include Commission officials.',false,'Independent means independent from the Commission; scientific means research-based members (official sample answer).'],
 ['Machine-generated text is protected by copyright as the machine’s original expression.',false,'Copyright protects original expression by a human; ideas and algorithms are not protected either.'],
 ['US fair use and the EU text-and-data-mining exceptions are the same rule.',false,'Fair use weighs four factors; the EU has a research exception (Art. 3) and a general exception with opt-out (Art. 4).'],
 ['Decoupling means official adoption of a tool can coexist with staff ignoring it.',true,'Meyer & Rowan (1977); Christin observed foot-dragging, gaming and open critique.'],
 ['Giving source code to citizens is a sufficient explanation of a decision.',false,'Explanations must fit their audience (experts, laypeople, regulators) and be selective and contrastive.'],
];
function paintTrap(){if(G.i>=G.items.length){const rec=setBest('trap',G.score+'/'+G.items.length,(a,b)=>parseInt(a)>parseInt(b));main.innerHTML=heading('Game · Trap or truth?',`Score ${G.score} / ${G.items.length}`,rec?'New best! 🏆':'')+`<div class="toolbar"><button class="primary" data-replay="trap">Play again</button>${link('#games','All games')}</div>`;return}
 const [s,v,why]=G.items[G.i];main.innerHTML=heading('Game · Trap or truth?',`Statement ${G.i+1} / ${G.items.length}`,'Score '+G.score)+`<div class="toolbar">${link('#games','← All games')}</div><section class="card quiz-q"><p class="quiz-def">${esc(s)}</p></section><div class="quiz-opts two">${[['True',true],['False / trap',false]].map(([t,b])=>`<button data-trap="${b}" class="${G.answered?(b===v?'right':(String(b)===G.picked?'wrong':'')):''}" ${G.answered?'disabled':''}>${t}</button>`).join('')}</div>${G.answered?`<section class="card"><p><strong>${v?'True.':'Trap!'}</strong> ${esc(why)}</p><button class="primary" data-trap-next>Next →</button></section>`:''}`}

document.addEventListener('click',e=>{const b=e.target.closest('button,[data-jump]');if(!b||!D)return;
 if(b.dataset.jump){document.getElementById(b.dataset.jump)?.scrollIntoView({behavior:'smooth'});return}
 if(b.dataset.pref){prefs[b.dataset.pref]=!prefs[b.dataset.pref];savePrefs();const st=window.scrollY;render();window.scrollTo(0,st);return}
 if(b.dataset.flash){const c=G.queue[0];if(b.dataset.flash==='flip')G.flipped=!G.flipped;if(b.dataset.flash==='known'){prefs.known[c.id]=1;savePrefs();G.queue.shift();G.flipped=false}if(b.dataset.flash==='again'){G.queue.push(G.queue.shift());G.flipped=false}if(b.dataset.flash==='reset'){deck(G.lec).forEach(c=>delete prefs.known[c.id]);savePrefs();return GAMES.flash(G.lec)}if(!G.queue.length)return GAMES.flash(G.lec);return paintFlash()}
 if(b.dataset.match){const side=b.dataset.match,id=b.dataset.id;if(!G.sel||G.sel.side===side){G.sel={side,id};return paintMatch()}if(G.sel.id===id){G.done.add(id);G.sel=null;if(G.done.size===G.pool.length)return finishMatch()}else{G.penalty+=3;G.sel=null;toast('Not a pair: +3 s')}return paintMatch()}
 if(b.dataset.quiz!==undefined&&!G.answered){G.answered=true;G.picked=b.dataset.quiz;if(G.picked===G.cur.ans.term){G.score++;G.streak++;G.best=Math.max(G.best,G.streak)}else G.streak=0;return paintQuiz()}
 if(b.hasAttribute('data-quiz-next'))return nextQuiz();
 if(b.dataset.trap!==undefined&&!G.answered){G.answered=true;G.picked=b.dataset.trap;if((b.dataset.trap==='true')===G.items[G.i][1])G.score++;return paintTrap()}
 if(b.hasAttribute('data-trap-next')){G.i++;G.answered=false;return paintTrap()}
 if(b.dataset.replay)return GAMES[b.dataset.replay](G.lec||'');
});
document.addEventListener('click',e=>{const li=e.target.closest('.recall .idea');if(li)li.classList.toggle('revealed')});
document.addEventListener('keydown',e=>{if(e.key==='Enter'){const li=e.target.closest&&e.target.closest('.recall .idea');if(li)li.classList.toggle('revealed')}});
document.addEventListener('input',e=>{if(e.target.id==='gloss-filter')filterGloss()});
document.addEventListener('change',e=>{if(e.target.id==='gloss-lecture')filterGloss();if(e.target.id==='kit-usecase')location.hash='kit'+(e.target.value?'/'+e.target.value:'');if(e.target.dataset.gameLecture)location.hash='game/'+e.target.dataset.gameLecture+(e.target.value?'/'+e.target.value:'')});
function extraSearch(includes){return [...D.lectures.flatMap(l=>l.parts.flatMap(p=>p.ideas.filter(includes).map(i=>['#lecture/'+l.id,l.id+' · '+i.key]))),...D.glossary.filter(includes).map(g=>['#glossary','Glossary · '+g.term]),...D.examMocks.flatMap(m=>m.questions.filter(includes).map(q=>['#exam/'+m.id,'Paper '+m.id+' · '+q.prompt]))]}

function viClue(v){const i=v.search(/[:=]/);return i>0&&i<70?'▢▢▢'+v.slice(i):v}
